'use strict';
const D=window.TRACE_DATA;
const CH=D.chapters, C=D.cards, Q=D.questions, A=D.artifacts, CM=D.commands, EX=D.exams, SRC=D.sources;
const CMap=Object.fromEntries(C.map(x=>[x.id,x])), QMap=Object.fromEntries(Q.map(x=>[x.id,x]));
const KEY='trace-security-revision-v1'; let storageOK=true, toastTimer, confirmResolve=null;
const fresh=()=>({version:1,app:'TRACE-SECURITY',theme:window.matchMedia?.('(prefers-color-scheme: dark)').matches?'dark':'light',sidebarCollapsed:false,zen:false,focus:focusDefaults(),mastered:[],bookmarks:[],notes:{},tdAnswers:{},tdChoices:{},tdDone:[],tdRevealed:[],attempts:[],stats:{},flashRatings:{},active:null,lastCard:null});
let state=fresh();
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&saved.app==='TRACE-SECURITY'&&saved.version===1)state={...state,...saved};}catch(e){storageOK=false;}
let filters={atlasCh:'all',atlasQ:'',cmdCh:'all',cmdQ:'',flashCh:'all',flashKind:'all',flashScope:'all',flashDeck:[],flashIdx:0,flashBack:false,correction:'all'};
let sourceView={chapter:1,page:1};
const iconPaths={home:'M3 10 12 3l9 7M5 9v11h5v-6h4v6h5V9',book:'M4 3h6a3 3 0 0 1 3 3v15a4 4 0 0 0-4-2H4zM13 6a3 3 0 0 1 3-3h5v16h-5a4 4 0 0 0-3 2',atlas:'M9 3 3 6v15l6-3 6 3 6-3V3l-6 3zM9 3v15M15 6v15',terminal:'m5 7 5 5-5 5M13 17h6',layers:'m12 3 10 5-10 5L2 8zM2 12l10 5 10-5M2 16l10 5 10-5',exam:'M8 4H5v17h14V4h-3M8 2h8v4H8zM8 11h8M8 16h5',error:'M12 8v5M12 17h.01M10 3 2 18a2 2 0 0 0 2 3h16a2 2 0 0 0 2-3L14 3a2 2 0 0 0-4 0',file:'M14 2H5v20h14V7zM14 2v5h5M8 12h8M8 16h6',chart:'M4 3v18h17M8 16v-4M13 16V7M18 16v-7',lab:'M9 3h6M10 3v6l-6 10a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2L14 9V3M8 15h8',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',moon:'M20 14A9 9 0 0 1 10 3a9 9 0 1 0 10 11',sun:'M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5l1.5 1.5M5 19l1.5-1.5M17.5 6.5l1.5-1.5M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',flag:'M5 22V3m0 0c4-3 8 3 14 0v10c-6 3-10-3-14 0',star:'m12 3 3 6 6 .9-4.5 4.4L17.6 21 12 18l-5.6 3 1.1-6.7L3 9.9 6 9z',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',print:'M7 7V2h10v5M7 17H3V8h18v9h-4M7 14h10v8H7zM17 11h.01',info:'M12 11v6M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',menu:'M4 6h16M4 12h16M4 18h16',refresh:'M20 7V2m0 5h-5M4 17v5m0-5h5M20 7a9 9 0 0 0-16 3M4 17a9 9 0 0 0 16-3',lock:'M6 10V7a6 6 0 0 1 12 0v3M4 10h16v12H4zM12 14v4',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',settings:'M4 5h16M4 12h16M4 19h16M8 2v6M16 9v6M10 16v6',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7',play:'m8 4 12 8-12 8z'};
function icon(name,extra=''){return `<svg class="icon ${extra}" aria-hidden="true" viewBox="0 0 24 24"><path d="${iconPaths[name]||iconPaths.file}"/></svg>`;}
function E(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function norm(s){return String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
function matches(text,query){return norm(query).trim().split(/\s+/).every(t=>norm(text).includes(t));}
function shuffled(arr){const a=arr.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){storageOK=false;showStorageWarning();}}
function showStorageWarning(){if(document.getElementById('storage-warning'))return;const x=document.createElement('div');x.id='storage-warning';x.className='warning-strip';x.textContent='Le navigateur bloque la sauvegarde locale. Ta session reste disponible ici ; exporte ta progression avant de fermer.';document.body.append(x);}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.remove('hide');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.add('hide'),3000);}
function closeDialogs(){document.querySelectorAll('dialog[open]').forEach(d=>d.close());}
function ask(title,body,yes='Confirmer'){return new Promise(resolve=>{confirmResolve=resolve;document.getElementById('confirm-dialog').innerHTML=`<div class="dialog-head"><h2>${E(title)}</h2><button class="iconbtn" data-action="confirm-no" aria-label="Annuler">${icon('close')}</button></div><div class="dialog-body"><p class="muted" style="font-size:13px">${E(body)}</p><div class="dialog-actions"><button class="btn" data-action="confirm-no">Annuler</button><button class="btn primary" data-action="confirm-yes">${E(yes)}</button></div></div>`;document.getElementById('confirm-dialog').showModal();});}
function go(route){const h='#/'+route;if(location.hash===h)render();else location.hash=h;}
function route(){return (location.hash.replace(/^#\/?/,'')||'home').split('/').map(x=>{try{return decodeURIComponent(x)}catch(e){return x}});}
const chapter=id=>CH.find(c=>c.id===Number(id));
const chapterCards=id=>C.filter(c=>c.chapter===Number(id));
const refsOf=x=>x.refs||x.pages.map(p=>[x.chapter,p]);
function refs(refArray){const unique=[...new Map((refArray||[]).map(x=>[x.join('-'),x])).values()];return `<div class="row wrap sources">${unique.map(([c,p])=>`<button class="source-pill" data-action="source" data-ch="${c}" data-page="${p}" title="Ouvrir ${c===5?'le TD, page':'le chapitre '+c+', diapositive'} ${p}">${icon('file')} ${c===5?'TD · p.':'C'+c+' · diapo'} ${p}</button>`).join('')}</div>`;}
function completed(ch){return chapterCards(ch).filter(c=>state.mastered.includes(c.id)).length;}
function errorIds(){return Object.entries(state.stats).filter(([id,x])=>QMap[id]&&x.lastCorrect===false).map(([id])=>id);}
function attemptsFor(id){return state.attempts.filter(a=>a.examId===id);}
function score(a){return a.qids.filter(id=>a.answers[id]===QMap[id]?.answer).length;}
function fmtDate(ms){return new Date(ms).toLocaleDateString('fr-FR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});}
function fmtTime(sec){sec=Math.max(0,Math.floor(sec));return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
function pct(n,d){return d?Math.round(n/d*100):0;}
function btn(text,act,iconName='',cls='',attrs=''){return `<button class="btn ${cls}" data-action="${act}" ${attrs}>${iconName?icon(iconName):''}${text}</button>`;}
function empty(title,text,action=''){return `<div class="card empty"><div class="empty-icon">${icon('layers')}</div><h2>${E(title)}</h2><p>${E(text)}</p>${action}</div>`;}
function pageHead(kicker,title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">${E(kicker)}</div><h1 tabindex="-1">${E(title)}</h1>${desc?`<p>${E(desc)}</p>`:''}</div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`;}
function render(){document.documentElement.dataset.theme=state.theme;nav();header();const r=route();let html;switch(r[0]){case 'td':html=renderTD();break;case 'methods':html=renderMethods();break;case 'focus':html=renderFocus();break;case 'chapters':html=renderChapters();break;case 'chapter':html=renderChapter(Number(r[1]),r[2]);break;case 'atlas':html=renderAtlas();break;case 'commands':html=renderCommands();break;case 'flashcards':html=renderFlash();break;case 'exams':html=renderExams();break;case 'quiz':html=renderQuiz();break;case 'result':html=renderResult(r[1]);break;case 'errors':html=renderErrors();break;case 'sources':html=renderSources();break;case 'labs':html=renderLabs();break;case 'progress':html=renderProgress();break;case 'bookmarks':html=renderBookmarks();break;default:html=renderHome();}document.getElementById('main').innerHTML=html+footer();document.title=`${r[0]==='chapter'&&chapter(r[1])?chapter(r[1]).short:'Protocoles de sécurité & cryptanalyse'} · TRACE`;updateClock();syncFocusUI();if(!storageOK)showStorageWarning();}
function renderHome(){const next=EX.find(e=>!attemptsFor(e.id).length)||EX[0];const last=CMap[state.lastCard]||C.find(c=>!state.mastered.includes(c.id))||C[0];const examsDone=EX.filter(e=>attemptsFor(e.id).length).length;return `<section class="welcome"><div><span class="pill blue"><span class="dot"></span> PROTOCOLES DE SÉCURITÉ & CRYPTANALYSE</span><h1>Comprendre le protocole.<br><span>Savoir l’expliquer.</span></h1><p>Du handshake TLS à la cryptanalyse : tes quatre chapitres, le TD de révision et des examens pour relier les notions.</p></div><div class="course-stamp"><div class="eyebrow">Supports consultables</div><strong>155 <span style="font-size:11px;letter-spacing:0;color:var(--muted)">pages</span></strong><div class="tiny muted">148 diapositives + 7 pages de TD</div></div></section><div class="stats"><div class="stat"><div class="stat-value">${C.length}</div><div class="stat-label">Fiches avec sources</div></div><div class="stat"><div class="stat-value">${Q.length}</div><div class="stat-label">Questions expliquées</div></div><div class="stat"><div class="stat-value">${examsDone}<span style="color:var(--subtle);font-size:16px"> / 10</span></div><div class="stat-label">Examens blancs terminés</div></div><div class="stat"><div class="stat-value">${pct(state.mastered.length,C.length)}<span style="font-size:17px"> %</span></div><div class="stat-label">Fiches déclarées maîtrisées</div></div></div>${focusHomeStrip()}${state.active?activeBanner():''}<div class="home-columns"><section><div class="section-head"><h2>Ton parcours de révision</h2><a class="small" href="#/chapters">Les fiches ${icon('arrow')}</a></div><div class="chapter-list">${CH.map(c=>`<a href="#/chapter/${c.id}" class="chapter-row"><span class="badge-no c${c.id}">0${c.id}</span><div><h3>${E(c.title)}</h3><p>${chapterCards(c.id).length} fiches · ${c.pages} diapositives · ${completed(c.id)} maîtrisées</p><div class="bar"><span style="width:${pct(completed(c.id),chapterCards(c.id).length)}%"></span></div></div>${icon('chevron')}</a>`).join('')}</div><a class="card td-home-banner" href="#/td"><span class="tile-icon">${icon('exam')}</span><div><div class="eyebrow">Le TD que tu as reçu</div><h3>Quatre exercices, étape par étape.</h3><p>TLS & PKI · Kasiski & IC · Rogue RA · QCM IPv6/EUI-64</p></div>${icon('arrow')}</a></section><aside><div class="section-head"><h2>Passer à l’entraînement</h2></div><div class="next-exam"><div class="eyebrow">Ton prochain sujet</div><h2>${E(next.title)}</h2><p>Notions, messages, calculs et scénarios. Sans commande à rédiger.</p><div class="exam-meta"><div><strong>40</strong><span>questions</span></div><div><strong>4</strong><span>chapitres</span></div><div><strong>60</strong><span>min proposées</span></div></div><a class="btn" href="#/exams">Choisir mon examen ${icon('arrow')}</a></div><div class="card quick-card"><div class="eyebrow" style="margin-bottom:12px">Reprendre le fil</div><a class="quick-item" href="#/chapter/${last.chapter}/${last.id}"><div><div style="font-weight:550">${state.lastCard?'Ma dernière fiche':'Commencer les fiches'}</div><div class="tiny muted" style="margin-top:3px">${E(last.title)}</div></div>${icon('chevron')}</a><a class="quick-item" href="#/errors"><span>Revoir mes erreurs</span><span class="pill ${errorIds().length?'amber':''}">${errorIds().length}</span></a><a class="quick-item" href="#/bookmarks"><span>Mes fiches favorites</span><span class="pill">${state.bookmarks.length}</span></a></div></aside></div><div class="home-bottom"><a class="card home-tile" href="#/atlas"><div class="tile-icon">${icon('atlas')}</div><div><h3>Les repères à reconnaître.</h3><p>${A.length} messages, champs et valeurs. Leur rôle, leur emplacement et leurs limites.</p></div></a><a class="card home-tile" href="#/methods"><div class="tile-icon">${icon('layers')}</div><div><h3>Comprendre le calcul.</h3><p>César, Vigenère, Kasiski, IC, EUI-64 et sous-réseaux, avec les étapes.</p></div></a></div><div class="notice space-sm">${icon('info')}<div><strong>Un espace indépendant de Forensics.</strong><p>Notes, scores, favoris et sessions focus sont sauvegardés pour ce module uniquement. Les sujets et les corrigés proposés ne sont pas des annales officielles.</p></div></div>`;}
function renderChapters(){return pageHead('Le cours, réorganisé','Les quatre chapitres.','Les fiches suivent les thèmes des quatre présentations. Chaque fiche contient une explication, les points essentiels, un piège de lecture et ses diapositives sources.',btn('Cartes mémoire','go','layers','','data-route="flashcards"'))+`<div class="chapter-grid">${CH.map(c=>`<section class="card chapter-cover"><div class="between"><span class="badge-no c${c.id}">0${c.id}</span><span class="pill">${c.pages} diapositives source</span></div><h2>${E(c.title)}</h2><p>${E(c.tagline)}</p><div class="bar"><span style="width:${pct(completed(c.id),chapterCards(c.id).length)}%"></span></div><div class="between tiny muted"><span>${completed(c.id)} / ${chapterCards(c.id).length} fiches maîtrisées</span><span>${c.parts.length} parties de révision</span></div><div class="chapter-cover-foot"><a class="btn primary" href="#/chapter/${c.id}">Ouvrir le chapitre ${icon('arrow')}</a><button class="btn ghost sm" data-action="chapter-quiz" data-ch="${c.id}">Me tester</button></div></section>`).join('')}</div><div class="notice space">${icon('info')}<div><strong>La théorie maintenant ; les labs dans un parcours distinct.</strong><p>Les outils et démonstrations des supports sont conservés pour comprendre leur rôle. Aucune commande à rédiger ou à exécuter n’est demandée.</p></div></div>`;}
function lessonIndex(card){return `<a class="lesson-index" href="#/chapter/${card.chapter}/${card.id}"><span class="toc-dot ${state.mastered.includes(card.id)?'done':''}">${state.mastered.includes(card.id)?icon('check'):''}</span><span>${E(card.title)}</span><span class="page">p. ${card.pages.join(', ')}</span></a>`;}
function renderChapter(id,cardId){const c=chapter(id);if(!c)return empty('Chapitre introuvable','Choisis l’un des quatre chapitres.',`<a class="btn" href="#/chapters">Les chapitres</a>`);const list=chapterCards(id);const cur=CMap[cardId];const toc=`<aside class="study-toc" aria-label="Sommaire du chapitre"><a class="toc-link ${!cur?'active':''}" href="#/chapter/${id}">${icon('book')} Vue du chapitre</a>${c.parts.map((part,i)=>`<span class="toc-title">${i+1}. ${E(part)}</span>${list.filter(x=>x.part===i).map(x=>`<a class="toc-link ${cur?.id===x.id?'active':''}" href="#/chapter/${id}/${x.id}" ${cur?.id===x.id?'aria-current="page"':''}><span class="toc-dot ${state.mastered.includes(x.id)?'done':''}">${state.mastered.includes(x.id)?icon('check'):''}</span><span>${E(x.title)}</span></a>`).join('')}`).join('')}</aside>`;let body;if(cur&&cur.chapter===id){state.lastCard=cur.id;save();const idx=list.findIndex(x=>x.id===cur.id);body=`<article><div class="card lesson"><div class="between wrap"><span class="pill">Fiche ${String(idx+1).padStart(2,'0')} / ${list.length}</span>${refs(refsOf(cur))}</div><h2>${E(cur.title)}</h2><p class="lesson-summary">${E(cur.summary)}</p><div class="eyebrow">Ce qu’il faut comprendre</div><ol class="lesson-points">${cur.points.map(p=>`<li>${E(p)}</li>`).join('')}</ol>${cur.trap?`<div class="notice warning">${icon('error')}<div><strong>Le point de vigilance</strong><p>${E(cur.trap)}</p></div></div>`:''}<div class="lesson-recall"><div class="eyebrow">À expliquer sans regarder</div><p>${E(cur.recall)}</p></div><div class="lesson-tools">${btn(state.mastered.includes(cur.id)?'Fiche maîtrisée':'Marquer comme maîtrisée','master','check',state.mastered.includes(cur.id)?'':'primary',`data-id="${cur.id}"`)}${btn(state.bookmarks.includes(cur.id)?'Dans mes favoris':'Garder cette fiche','bookmark','star','',`data-id="${cur.id}"`)}${btn('Imprimer','print-lesson','print','ghost')}</div><label class="note-label" for="personal-note">Mes notes <span class="tiny" id="note-status">· sauvegarde locale</span></label><textarea id="personal-note" class="note-field" data-note="${cur.id}" placeholder="Une reformulation avec tes mots, un point à demander au professeur…">${E(state.notes[cur.id]||'')}</textarea><div class="space-sm">${refs(refsOf(cur))}${externalNote(cur)}</div><div class="print-source" style="display:none">Source : chapitre ${id}, diapositives ${cur.pages.join(', ')}.</div></div><div class="lesson-nav">${idx>0?`<a class="btn" href="#/chapter/${id}/${list[idx-1].id}">${icon('back')} Fiche précédente</a>`:'<span></span>'}${idx<list.length-1?`<a class="btn" href="#/chapter/${id}/${list[idx+1].id}">Fiche suivante ${icon('arrow')}</a>`:btn('Tester ce chapitre','chapter-quiz','exam','primary',`data-ch="${id}"`)}</div></article>`;}else{body=`<div><div class="study-banner"><div class="between wrap"><div><h3>${E(c.tagline)}</h3><p>${list.length} fiches · ${completed(id)} maîtrisées · 100 questions disponibles pour ce chapitre</p></div>${btn('Me tester · 40 questions','chapter-quiz','exam','',`data-ch="${id}"`)}</div></div><div class="overview-parts">${c.parts.map((part,i)=>`<section class="overview-section"><h3>${String(i+1).padStart(2,'0')} <span class="muted" style="margin-left:8px">${E(part)}</span></h3>${list.filter(x=>x.part===i).map(lessonIndex).join('')}</section>`).join('')}</div></div>`;}return pageHead(`Chapitre 0${id}`,c.title,cur?c.parts[cur.part]:'Lis les fiches dans l’ordre ou sélectionne une notion précise.',`<a class="btn ghost" href="#/chapters">${icon('back')} Les chapitres</a>`)+`<div class="study-layout">${toc}${body}</div>`;}
function chapterSelect(id,value='all',label='Tous les chapitres'){return `<select id="${id}" aria-label="Filtrer par chapitre"><option value="all" ${value==='all'?'selected':''}>${label}</option>${CH.map(c=>`<option value="${c.id}" ${String(c.id)===String(value)?'selected':''}>C${c.id} · ${E(c.short)}</option>`).join('')}</select>`;}
function filteredAtlas(){return A.filter(a=>(filters.atlasCh==='all'||a.chapter===Number(filters.atlasCh))&&matches([a.name,a.path,a.purpose,a.tool,a.limit].join(' '),filters.atlasQ));}
function atlasCards(){const items=filteredAtlas();return items.length?items.map(a=>`<article class="card ref-card"><div class="between"><h3>${E(a.name)}</h3><span class="pill">C${a.chapter}</span></div><div class="path">${E(a.path)}</div><p>${E(a.purpose)}</p><p class="tool"><strong>À distinguer :</strong> ${E(a.tool)}</p><details><summary>Le point de vigilance</summary><p>${E(a.limit)}</p></details>${refs(refsOf(a))}${externalNote(a)}</article>`).join(''):empty('Aucun repère trouvé','Essaie un autre nom, un numéro ou un autre chapitre.');}
function renderAtlas(){return pageHead('Les repères du module','Quel message, quel rôle ?','Messages TLS, champs IPsec, types ICMPv6 et méthodes de cryptanalyse. Cherche un nom, une valeur ou une fonction.')+`<div class="filters"><label class="searchbox">${icon('search')}<span class="sr">Rechercher un repère</span><input id="atlas-query" value="${E(filters.atlasQ)}" placeholder="Ex. CertificateVerify, 134, SPI, Kasiski…"></label>${chapterSelect('atlas-ch',filters.atlasCh)}<span class="filter-count" id="atlas-count">${filteredAtlas().length} repères</span></div><div id="atlas-grid" class="grid2">${atlasCards()}</div><section class="space"><div class="section-head"><h2>Les valeurs à distinguer</h2>${refs([[2,13],[2,22],[2,28]])}</div><div class="event-grid">${[['133','Router Solicitation'],['134','Router Advertisement'],['135','Neighbor Solicitation'],['136','Neighbor Advertisement'],['137','Redirect'],['6','Next Header : TCP'],['50','Next Header : ESP'],['51','Next Header : AH'],['58','Next Header : ICMPv6'],['255','Hop Limit des messages NDP du support'],['ff02::1','Tous les nœuds du lien'],['ff02::2','Tous les routeurs du lien']].map(([id,t])=>`<div class="event-cell"><strong>${id}</strong><span>${t}</span></div>`).join('')}</div></section>`;}
function filteredCommands(){return CM.filter(c=>(filters.cmdCh==='all'||c.chapter===Number(filters.cmdCh))&&matches([c.command,c.meaning,...c.parts,c.caution].join(' '),filters.cmdQ));}
function commandCards(){const items=filteredCommands();return items.length?items.map(c=>`<article class="card ref-card"><div class="between"><span class="eyebrow">Lecture ${c.id.replace('cmd','')}</span><span class="pill">Chapitre ${c.chapter}</span></div><pre class="command-block">${E(c.command)}</pre><h3 style="font-size:14px">${E(c.meaning)}</h3><ul class="command-parts">${c.parts.map(p=>`<li>${E(p)}</li>`).join('')}</ul><details><summary>Limite ou précaution</summary><p>${E(c.caution)}</p></details>${refs(refsOf(c))}</article>`).join(''):empty('Aucune commande trouvée','Essaie le nom de l’outil ou l’information que tu veux obtenir.');}
function renderCommands(){return pageHead('Interpréter, pas rédiger','Que fait cette commande ?','Lire les filtres Wireshark et les options OpenSSL du chapitre TLS. Aucune commande ne s’exécute dans cette application.',btn('Tester ma compréhension','command-quiz','exam','primary'))+`<div class="notice" style="margin-bottom:23px">${icon('info')}<div><strong>SNI n’est pas une vérification du nom.</strong><p>Le support distingue -servername, -verify_hostname et -verify_return_error. Les exemples servent à reconnaître un rôle, pas à réaliser un TP ici.</p></div></div><div class="filters"><label class="searchbox">${icon('search')}<span class="sr">Rechercher une commande</span><input id="cmd-query" value="${E(filters.cmdQ)}" placeholder="Ex. tls, 8443, servername, SAN…"></label>${chapterSelect('cmd-ch',filters.cmdCh)}<span class="filter-count" id="cmd-count">${filteredCommands().length} fiches</span></div><div id="cmd-grid" class="grid2">${commandCards()}</div>`;}
function activeBanner(){const a=state.active;if(!a)return '';return `<div class="active-banner between wrap"><div><div style="font-size:13px;font-weight:600">${icon('clock')} Une session est en cours</div><div class="small muted" style="margin-top:5px">${E(a.title)} · ${Object.keys(a.answers).length} / ${a.qids.length} réponses · ${a.mode==='practice'?'entraînement':'examen'}</div></div><div class="row">${btn('Reprendre','go','arrow','primary','data-route="quiz"')}${btn('Abandonner','discard','','ghost sm')}</div></div>`;}
function renderExams(){return pageHead('S’entraîner en conditions simulées','Les examens blancs.','Dix sujets distincts de 40 questions : 10 par chapitre, sans répétition entre les dix sujets. Une seule bonne réponse par question.')+activeBanner()+`<div class="exam-intro"><section class="card"><div class="row">${icon('exam')}<h2>Le cadre de la simulation</h2></div><p class="exam-rules">40 questions · 1 point par bonne réponse · 0 point sinon · pas de pénalité. Le corrigé arrive à la remise de la copie, avec explications, diapositives sources et bilan par chapitre.</p><div class="row wrap space-sm"><label for="exam-minutes" class="small muted">Durée proposée</label><select id="exam-minutes">${[[60,'60 minutes'],[90,'90 minutes'],[120,'120 minutes'],[0,'Sans chronomètre']].map(([n,t])=>`<option value="${n}" ${Number(state.defaultMinutes??60)===n?'selected':''}>${t}</option>`).join('')}</select></div><p class="tiny muted" style="margin-top:14px">Le format, la durée et le barème sont des choix d’entraînement. Les sujets ne sont ni des annales ni des examens validés par l’enseignant. Un examen chronométré continue même si tu quittes cette vue.</p></section><section class="card"><div class="eyebrow">Entraînement personnalisé</div><h2 style="margin:10px 0 17px;font-size:18px">Cibler une difficulté.</h2><div class="form-grid"><label>Chapitre${chapterSelect('custom-ch')}</label><label>Type de question<select id="custom-kind"><option value="all">Tous les types</option value="notion">Notions</option><option value="emplacement">Emplacements</option><option value="commande">Commandes à lire</option><option value="cas">Mini-cas</option><option value="lecture">Messages & lecture</option><option value="calcul">Calculs</option></select></label><label>Nombre<select id="custom-count"><option>10</option><option>20</option><option selected>40</option></select></label><label>Correction<select id="custom-mode"><option value="practice">Après chaque question</option><option value="exam">À la fin</option></select></label></div><div class="between space-sm">${btn('Lancer la sélection','custom-quiz','play','primary')}<span class="tiny muted" id="custom-available">${Q.length} disponibles</span></div><p class="tiny muted" style="margin-top:12px">Sans chrono. Le nombre est limité aux questions disponibles. Ces sélections réutilisent la banque des dix sujets.</p></section></div><div class="section-head"><h2>Les dix sujets</h2><span class="pill">${Q.length} questions distinctes</span></div><div class="exam-cards">${EX.map((ex,i)=>{const at=attemptsFor(ex.id),best=at.length?Math.max(...at.map(score)):null;return `<article class="card exam-card"><div class="between"><span class="exam-number">SUJET / ${String(i+1).padStart(2,'0')}</span>${at.length?'<span class="pill green">Terminé</span>':'<span class="pill">À découvrir</span>'}</div><h3>${E(ex.title)}</h3><p>40 questions · 10 par chapitre<br>Notions, messages, calculs et raisonnement.</p><div class="between"><span class="${at.length?'score-mini':'tiny muted'}">${at.length?`Meilleur : ${best} / 40`:'Pas encore de tentative'}</span><button class="iconbtn" data-action="print-subject" data-exam="${ex.id}" aria-label="Imprimer le sujet ${i+1}" title="Imprimer sans corrigé">${icon('print')}</button></div>${btn(at.length?'Repasser le sujet':'Commencer','start-exam','arrow','primary',`data-exam="${ex.id}"`)}</article>`}).join('')}</div><div class="notice space">${icon('info')}<div><strong>Des interprétations, pas des lignes de commande à inventer.</strong><p>Les questions portent sur le rôle d’un outil, une option affichée, un emplacement, un calcul, une différence de concepts ou les limites d’une conclusion.</p></div></div>`;}
async function startQuiz(ids,title,{mode='exam',examId=null,minutes=0}={}){ids=[...new Set(ids)].filter(id=>QMap[id]);if(!ids.length){toast('Aucune question ne correspond à cette sélection.');return;}if(state.active){const ok=await ask('Remplacer la session en cours ?','La session non remise sera abandonnée. Les tentatives déjà terminées restent conservées.','Nouvelle session');if(!ok)return;}const now=Date.now();state.active={id:'attempt-'+now,examId,title,mode,qids:ids,answers:{},flags:{},checked:{},current:0,startedAt:now,duration:minutes>0?minutes*60:null,deadline:minutes>0?now+minutes*60000:null};save();go('quiz');}
function getSelected(id,fallback){return document.getElementById(id)?.value??fallback;}
function chooseBalanced(pool,n){const groups=CH.map(ch=>shuffled(pool.filter(q=>q.chapter===ch.id)));const selected=[];let index=0;while(selected.length<Math.min(n,pool.length)){const g=groups[index%groups.length];if(g.length)selected.push(g.pop().id);index++;}return shuffled(selected);}
function customPool(){const ch=getSelected('custom-ch','all'),kind=getSelected('custom-kind','all');return Q.filter(q=>(ch==='all'||q.chapter===Number(ch))&&(kind==='all'||q.kind===kind));}
function renderQuiz(){const a=state.active;if(!a)return pageHead('Session','Aucune session en cours.','')+empty('Choisir un sujet','Lance un examen blanc ou une sélection d’entraînement.',`<a class="btn primary" href="#/exams">Les examens blancs</a>`);a.current=Math.max(0,Math.min(a.current,a.qids.length-1));const q=QMap[a.qids[a.current]],ans=a.answers[q.id],checked=a.mode==='practice'&&a.checked[q.id],answered=Object.keys(a.answers).length;const kind={notion:'Notion',emplacement:'Emplacement',commande:'Lecture de commande',cas:'Mini-cas',lecture:'Lecture',calcul:'Calcul'}[q.kind];return pageHead(a.mode==='practice'?'Entraînement avec correction':'Examen · correction à la remise',a.title,`${a.qids.length} questions · Une seule réponse par question. Tes choix sont sauvegardés localement.`,btn('Revenir aux sujets','go','back','ghost','data-route="exams"'))+`<div class="quiz-layout"><section class="card question-panel"><div class="quiz-top"><span class="eyebrow">Question ${String(a.current+1).padStart(2,'0')} / ${a.qids.length}</span><div class="row wrap"><span class="pill">C${q.chapter} · ${E(chapter(q.chapter).short)}</span><span class="pill blue">${kind}</span></div></div><h2 id="question-title">${E(q.stem)}</h2><div class="options" role="group" aria-labelledby="question-title">${q.options.map((option,i)=>`<button class="option ${ans===i?'selected':''} ${checked&&i===q.answer?'correct':''} ${checked&&ans===i&&ans!==q.answer?'incorrect':''}" data-action="answer" data-index="${i}" aria-pressed="${ans===i}" ${checked?'disabled':''}><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${E(option)}</span>${checked&&i===q.answer?icon('check'):''}</button>`).join('')}</div>${checked?feedback(q,ans):''}<div class="quiz-bottom"><button class="btn ghost sm" data-action="flag">${icon('flag')} ${a.flags[q.id]?'Signalée pour relecture':'À revoir avant remise'}</button><div class="row wrap"><button class="btn" data-action="q-prev" ${a.current===0?'disabled':''}>${icon('back')} Précédente</button>${a.mode==='practice'&&!checked?btn('Vérifier','check-answer','check','primary'):btn(a.current===a.qids.length-1?'Voir le bilan':'Suivante',a.current===a.qids.length-1?'submit':'q-next','arrow','primary')}</div></div><p class="tiny muted" style="margin-top:16px">Raccourcis : 1–4 pour choisir · ← / → pour naviguer. Aucune commande n’est exécutée.</p></section><aside class="card quiz-map"><div class="eyebrow">${a.deadline?'Temps restant':'Session libre'}</div><div id="quiz-timer" class="timer">${a.deadline?fmtTime((a.deadline-Date.now())/1000):'Sans chrono'}</div><div class="between small"><span class="muted">Réponses choisies</span><strong>${answered} / ${a.qids.length}</strong></div><div class="bar" style="margin-top:10px"><span style="width:${pct(answered,a.qids.length)}%"></span></div><nav class="q-grid" aria-label="Naviguer parmi les questions">${a.qids.map((id,i)=>`<button class="q-dot ${Object.hasOwn(a.answers,id)?'answered':''} ${i===a.current?'current':''} ${a.flags[id]?'flagged':''}" data-action="q-jump" data-index="${i}" aria-label="Question ${i+1}${Object.hasOwn(a.answers,id)?', réponse choisie':''}${a.flags[id]?', signalée':''}" ${i===a.current?'aria-current="step"':''}>${i+1}</button>`).join('')}</nav><div class="q-legend"><span>Bleu : réponse choisie</span><span>Point : à revoir</span></div>${btn(a.mode==='practice'?'Terminer l’entraînement':'Remettre ma copie','submit','check','ink')}<p class="tiny muted" style="margin-top:14px">${a.mode==='practice'?'La correction peut être consultée question par question. Le bilan comptabilise les choix de la session.':'Les questions sans réponse comptent 0. À la fin du chrono, la copie est remise automatiquement à la prochaine activité de la page.'}</p></aside></div>`;}
function feedback(q,ans){return `<div class="feedback ${ans===q.answer?'':'bad'}" role="status"><strong>${ans===q.answer?'Bonne réponse.':'La réponse attendue est différente.'}</strong>${ans!==q.answer?`<p style="margin-bottom:8px">${E(q.options[q.answer])}</p>`:''}<p>${E(q.explanation)}</p>${refs(refsOf(q))}${externalNote(q)}</div>`;}
let finalizing=false;
async function submitQuiz(auto=false){const a=state.active;if(!a||finalizing)return;if(!auto){const blanks=a.qids.filter(id=>!Object.hasOwn(a.answers,id)).length;const flags=Object.values(a.flags).filter(Boolean).length;const ok=await ask(a.mode==='practice'?'Terminer cet entraînement ?':'Remettre cette copie ?',`${blanks?`${blanks} question${blanks>1?'s':''} sans réponse compter${blanks>1?'ont':'a'} 0. `:'Toutes les questions ont une réponse. '}${flags?`${flags} question${flags>1?'s sont signalées':' est signalée'} pour relecture. `:''}La correction et le bilan seront ensuite affichés.`,a.mode==='practice'?'Voir le bilan':'Remettre');if(!ok||!state.active||state.active.id!==a.id)return;}finalizing=true;if(auto){if(confirmResolve){const r=confirmResolve;confirmResolve=null;r(false);}closeDialogs();}const now=Date.now();const attempt={id:a.id,examId:a.examId,title:a.title,mode:a.mode,qids:a.qids.slice(),answers:{...a.answers},flags:{...a.flags},date:now,elapsed:Math.min(Math.max(0,Math.floor((now-a.startedAt)/1000)),a.duration||Infinity),duration:a.duration,timeout:auto};for(const id of a.qids){const prev=state.stats[id]||{tries:0,correct:0};const ok=a.answers[id]===QMap[id].answer;state.stats[id]={tries:prev.tries+1,correct:prev.correct+(ok?1:0),lastCorrect:ok,lastAt:now};}state.attempts.unshift(attempt);state.attempts=state.attempts.slice(0,100);state.active=null;save();filters.correction='all';finalizing=false;go('result/'+attempt.id);}
function updateClock(){const a=state.active;if(!a||!a.deadline)return;const left=Math.ceil((a.deadline-Date.now())/1000);const el=document.getElementById('quiz-timer');if(el){el.textContent=fmtTime(left);el.classList.toggle('urgent',left<=300);}if(left<=0)submitQuiz(true);}
function correctionCard(q,a,number){const ans=a.answers[q.id],ok=ans===q.answer;return `<article class="card correction"><div class="between wrap"><div class="row"><span class="pill ${ok?'green':'red'}">${ok?'Correcte':ans===undefined?'Sans réponse':'À revoir'}</span><span class="tiny muted">${number?`Question ${number} · `:''}C${q.chapter} · ${E(q.difficulty)}</span></div>${refs(refsOf(q))}</div><h3>${E(q.stem)}</h3>${!ok?`<div class="answer-line wrong"><strong>Ta réponse :</strong> ${ans===undefined?'Aucune réponse':E(q.options[ans])}</div>`:''}<div class="answer-line"><strong>Réponse attendue :</strong> ${E(q.options[q.answer])}</div><p>${E(q.explanation)}</p>${externalNote(q)}${btn('Revoir une fiche liée','related-card','book','ghost sm',`data-q="${q.id}"`)}</article>`;}
function renderResult(id){const a=state.attempts.find(x=>x.id===id);if(!a)return empty('Bilan introuvable','Il n’est pas conservé dans la progression de ce navigateur.',`<a class="btn" href="#/progress">Ma progression</a>`);const s=score(a),n=a.qids.length;const stats=CH.map(c=>{const ids=a.qids.filter(id=>QMap[id].chapter===c.id);return{c,n:ids.length,good:ids.filter(id=>a.answers[id]===QMap[id].answer).length};}).filter(x=>x.n);const weak=stats.slice().sort((a,b)=>(a.good/a.n)-(b.good/b.n))[0];const filtered=a.qids.filter(id=>filters.correction!=='wrong'||a.answers[id]!==QMap[id].answer);return pageHead('Copie corrigée',a.title,`${fmtDate(a.date)} · ${a.mode==='practice'?'Entraînement':'Examen simulé'} · ${a.timeout?'Remise automatique à expiration du temps':'Session terminée'}`,btn('Imprimer le corrigé','print-correction','print','',`data-attempt="${a.id}"`))+`<section class="card results-hero"><div class="score-disk" style="--score:${pct(s,n)}"><div class="score-inner"><strong>${s}<span style="display:inline;font-size:17px"> / ${n}</span></strong><span>${pct(s,n)} % de bonnes réponses</span><span style="margin-top:5px">${(s/n*20).toFixed(1).replace('.',',')} / 20 · barème simulé</span></div></div><div><div class="between wrap"><h2>Ce que montre cette copie</h2><span class="pill">${fmtTime(a.elapsed)} de session</span></div><div class="space-sm">${stats.map(x=>`<div class="result-chapter"><span>C${x.c.id} · ${E(x.c.short)}</span><div class="bar"><span style="width:${pct(x.good,x.n)}%"></span></div><strong>${x.good}/${x.n}</strong></div>`).join('')}</div><div class="row wrap space-sm">${s<n?btn('Retravailler ces erreurs','retry-attempt','refresh','primary',`data-attempt="${a.id}"`):btn('Nouvelle sélection','random-quiz','refresh','primary')}<a class="btn" href="#/chapter/${weak.c.id}">Revoir ${E(weak.c.short)}</a></div></div></section><div class="section-head"><h2>Le corrigé expliqué</h2><select id="correction-filter" aria-label="Filtrer la correction"><option value="all" ${filters.correction==='all'?'selected':''}>Toutes les questions (${n})</option><option value="wrong" ${filters.correction==='wrong'?'selected':''}>Mes erreurs (${n-s})</option></select></div>${filtered.length?filtered.map(id=>correctionCard(QMap[id],a,a.qids.indexOf(id)+1)).join(''):empty('Aucune erreur dans cette copie.','Toutes les réponses correspondent au corrigé du sujet.')}<div class="notice space">${icon('info')}<div>Un score de simulation mesure cette sélection, pas une garantie de note à l’examen. Les questions et corrections sont créées à partir des supports, avec les divergences du cours signalées.</div></div>`;}
function renderErrors(){const ids=errorIds();return pageHead('Révision ciblée','Mes erreurs à retravailler.','Les questions dont ta dernière réponse enregistrée est incorrecte ou absente. Une nouvelle réponse juste dans une session terminée les retire de cette liste.',ids.length?btn('M’entraîner sur mes erreurs','errors-quiz','refresh','primary'):'')+(ids.length?`<div class="notice" style="margin-bottom:24px">${icon('info')}<div>${ids.length} question${ids.length>1?'s':''} à revoir. Les cartes mémoire ont leur propre classement personnel ; elles ne modifient pas les scores de tes copies.</div></div>${ids.map(id=>{const q=QMap[id];const a=state.attempts.find(a=>a.qids.includes(id));return a?correctionCard(q,a):`<div class="card correction"><h3>${E(q.stem)}</h3><p>${E(q.explanation)}</p>${refs(refsOf(q))}</div>`}).join('')}`:empty('Rien à retravailler ici pour le moment.','Les erreurs apparaîtront après une copie remise. Tu peux lancer un premier sujet ou continuer les fiches.',`<a class="btn primary" href="#/exams">Choisir un examen</a>`));}
function buildFlashDeck(){let pool=Q.filter(q=>(filters.flashCh==='all'||q.chapter===Number(filters.flashCh))&&(filters.flashKind==='all'||q.kind===filters.flashKind));if(filters.flashScope==='review')pool=pool.filter(q=>state.flashRatings[q.id]==='review');if(filters.flashScope==='errors'){const ids=new Set(errorIds());pool=pool.filter(q=>ids.has(q.id));}filters.flashDeck=shuffled(pool.map(q=>q.id));filters.flashIdx=0;filters.flashBack=false;}
function renderFlash(){if(!filters.flashDeck.length)buildFlashDeck();const ids=filters.flashDeck,q=QMap[ids[filters.flashIdx]];return pageHead('Rappel actif','Les cartes mémoire.','Formule la réponse avant de la révéler. Ces cartes reprennent les 400 questions de la banque, sans note ni chronomètre.')+`<div class="filters">${chapterSelect('flash-ch',filters.flashCh)}<select id="flash-kind" aria-label="Type de cartes">${[['all','Tous les types'],['notion','Notions'],['emplacement','Emplacements'],['commande','Commandes'],['cas','Mini-cas'],['lecture','Messages & lecture'],['calcul','Calculs']].map(([v,l])=>`<option value="${v}" ${filters.flashKind===v?'selected':''}>${l}</option>`).join('')}</select><select id="flash-scope" aria-label="Sélection de cartes">${[['all','Toute la sélection'],['review','Marquées « à revoir »'],['errors','Erreurs des examens']].map(([v,l])=>`<option value="${v}" ${filters.flashScope===v?'selected':''}>${l}</option>`).join('')}</select>${btn('Mélanger','flash-shuffle','refresh','ghost')}</div>${q?`<div class="flash-wrapper"><div class="flash-index">${String(filters.flashIdx+1).padStart(2,'0')} / ${ids.length} · CHAPITRE ${q.chapter}</div><section class="card flash-card"><div class="flash-label">${filters.flashBack?'La réponse et son explication':'D’abord, avec tes mots'}</div>${filters.flashBack?`<div class="small muted" style="margin-bottom:15px">${E(q.stem)}</div><div class="flash-answer">${E(q.options[q.answer])}</div><p class="flash-explain">${E(q.explanation)}</p><div class="row" style="justify-content:center;margin-top:22px">${refs(refsOf(q))}</div>`:`<h2>${E(q.stem)}</h2><details style="margin-top:22px;text-align:left;font-size:12px;color:var(--muted)"><summary style="cursor:pointer;text-align:center">Afficher les quatre propositions comme indices</summary><ul>${q.options.map(o=>`<li style="margin-top:8px">${E(o)}</li>`).join('')}</ul></details>`}</section><div class="flash-actions">${filters.flashBack?`${btn('À revoir','flash-rate','refresh','',`data-rating="review"`)}${btn('Acquis pour moi','flash-rate','check','primary',`data-rating="known"`)}`:btn('Révéler la réponse','flash-flip','eye','primary')}${btn('Passer','flash-next','arrow','ghost')}</div><p class="tiny muted" style="text-align:center">Espace : révéler/masquer · → : suivante · Ces auto-évaluations ne changent pas les notes.</p></div>`:empty('Aucune carte dans cette sélection.','Change le filtre ou marque des cartes « à revoir » pour créer ton propre paquet.')}`;}
function renderSources(){return pageHead('Le cours derrière chaque fiche','Supports & nuances.','Les numéros C1–C4 suivent l’ordre des diapositives dans les fichiers, pas leur pagination imprimée. Le TD utilise ses pages 1 à 7.')+`<div class="grid2">${SRC.map(s=>`<article class="card source-card"><div class="source-doc-icon">${icon('file')}</div><div style="min-width:0;flex:1"><h3>${s.id===5?'TD':'C'+s.id} · ${E(s.title)}</h3><p>${E(s.name)}</p><span class="pill">${s.count} ${s.id===5?'pages':'diapositives'}</span></div>${btn('Lire','source','book','sm',`data-ch="${s.id}" data-page="1"`)}</article>`).join('')}</div><div class="notice space">${icon('eye')}<div><strong>Les 155 pages sont intégrées en images et en texte.</strong><p>Les schémas, tableaux et formules restent consultables hors ligne. ${D.bundle?'Le dossier contient aussi les quatre PowerPoint originaux, leurs exports PDF et le TD original.':'Le ZIP complet ajoute les quatre PowerPoint originaux, leurs exports PDF et le TD original.'}</p></div></div><section class="space"><div class="section-head"><h2>Lire les supports sans confondre leurs nuances.</h2><span class="pill">${D.notes.length} notes</span></div>${D.notes.map(n=>`<details class="card note-card"><summary>${icon('info')} ${E(n.title)}</summary><p>${E(n.body)}</p>${refs(n.refs)}${externalNote(n)}</details>`).join('')}</section><section class="space"><h2>Compléments explicitement séparés</h2><p class="small muted space-sm">Le TD pose des questions de forme canonique et d’EUI-64 sans en détailler toutes les règles. Ces deux références complètent uniquement leur méthode.</p><div class="grid2 space-sm">${D.externals.map(s=>`<article class="card ref-card"><h3>${E(s.title)}</h3><p>${E(s.scope)}</p><a class="btn sm" href="${E(s.url)}" target="_blank" rel="noopener">Lire la référence ${icon('external')}</a></article>`).join('')}</div></section><div class="notice space">${icon('lock')}<div><strong>Périmètre et statut des corrections</strong><p>Les fiches reformulent les quatre cours ; les exercices du TD sont repris avec des résolutions proposées, non fournies par l’enseignant. Les dix examens sont créés pour l’entraînement. Les calculs déduits et compléments sont signalés. Aucun parcours pratique n’est présenté comme exécuté ou validé.</p></div></div>`;}
function renderLabs(){return pageHead('Parcours séparé','Les travaux pratiques.','La théorie, les calculs et le TD sont intégrés. Les manipulations sur machines restent un parcours distinct.')+`<section class="card lab-placeholder"><span class="pill amber">Labs non intégrés</span><div style="margin-top:27px;color:var(--muted)">${icon('lab')}</div><h2>Comprendre maintenant.<br>Manipuler ensuite.</h2><p>Le cours présente OpenSSL, Wireshark et des scénarios réseau. Leurs rôles sont expliqués dans les fiches et le TD ; aucun service ni paquet réseau n’est lancé par ce site.</p><div class="divider"></div><p>Les futurs supports de TP permettront d’ajouter les prérequis, les étapes, les sorties attendues et les erreurs à éviter, sans les mélanger aux examens théoriques.</p><div class="row wrap space"><a href="#/commands" class="btn">Lire les commandes ${icon('arrow')}</a><a href="#/td" class="btn primary">Travailler le TD ${icon('arrow')}</a></div></section>`;}
function renderBookmarks(){const cards=C.filter(c=>state.bookmarks.includes(c.id));return pageHead('Mes repères','Les fiches gardées.','Retrouve les notions que tu as ajoutées à tes favoris.')+(cards.length?cards.map(lessonIndex).join(''):empty('Aucune fiche favorite.','Dans une fiche, utilise « Garder cette fiche » pour la retrouver ici.',`<a class="btn primary" href="#/chapters">Parcourir les chapitres</a>`));}
function renderProgress(){const unique=Object.keys(state.stats).filter(id=>QMap[id]).length;return pageHead('Ton travail, conservé ici','Ma progression.','La maîtrise des fiches est déclarative. Les scores viennent des copies remises. Tu peux sauvegarder et transférer ta progression avec un export JSON.')+`<div class="stats"><div class="stat"><div class="stat-value">${state.mastered.length}</div><div class="stat-label">Fiches maîtrisées / ${C.length}</div></div><div class="stat"><div class="stat-value">${unique}</div><div class="stat-label">Questions déjà évaluées / ${Q.length}</div></div><div class="stat"><div class="stat-value">${state.attempts.length}</div><div class="stat-label">Sessions conservées</div></div><div class="stat"><div class="stat-value">${errorIds().length}</div><div class="stat-label">Dernières réponses à revoir</div></div></div><section class="card"><div class="section-head"><h2>Chapitre par chapitre</h2></div>${CH.map(c=>{const qs=Q.filter(q=>q.chapter===c.id&&state.stats[q.id]);const good=qs.filter(q=>state.stats[q.id].lastCorrect).length;return `<div class="settings-row"><div><h3>C${c.id} · ${E(c.short)}</h3><p>${completed(c.id)} / ${chapterCards(c.id).length} fiches maîtrisées · ${qs.length?`${good} / ${qs.length} dernières réponses correctes`:'Aucune question évaluée'}</p></div><a class="btn sm" href="#/chapter/${c.id}">Revoir ${icon('arrow')}</a></div>`}).join('')}</section><section class="space"><div class="section-head"><h2>Historique des copies</h2><span class="tiny muted">Les 100 dernières sessions au maximum</span></div>${state.attempts.length?`<div class="table-wrap"><table class="history-table"><thead><tr><th>SESSION</th><th>DATE</th><th>SCORE</th><th>MODE</th><th></th></tr></thead><tbody>${state.attempts.map(a=>`<tr><td>${E(a.title)}</td><td>${fmtDate(a.date)}</td><td><strong>${score(a)} / ${a.qids.length}</strong></td><td>${a.mode==='practice'?'Entraînement':'Examen'}</td><td><a href="#/result/${a.id}">Corrigé ${icon('arrow')}</a></td></tr>`).join('')}</tbody></table></div>`:empty('Pas encore de copie remise.','Les scores et les corrections apparaîtront ici après tes sessions.',`<a class="btn primary" href="#/exams">Commencer</a>`)}</section><section class="card space"><h2>Garder le contrôle de mes données</h2><div class="settings-row"><div><h3>Exporter ma progression</h3><p>Notes, favoris, maîtrise, réponses, historique et espace focus. À conserver avant de changer de navigateur ou de déplacer le site.</p></div>${btn('Exporter en JSON','export','download')}</div><div class="settings-row"><div><h3>Restaurer une sauvegarde</h3><p>L’import remplace la progression locale après confirmation.</p></div>${btn('Importer un JSON','import','upload')}</div><div class="settings-row"><div><h3>Repartir de zéro</h3><p>Supprime les notes et résultats de ce navigateur. Exporte d’abord une copie pour les garder.</p></div>${btn('Réinitialiser','reset','refresh','danger')}</div></section>`;}
function openSource(ch,page){const s=SRC.find(x=>x.id===Number(ch));if(!s)return;sourceView={chapter:s.id,page:Math.max(1,Math.min(Number(page)||1,s.count))};renderSource();const dlg=document.getElementById('source-dialog');if(!dlg.open)dlg.showModal();}
function renderSource(){const s=SRC.find(x=>x.id===sourceView.chapter),p=sourceView.page;if(!s)return;const img=s.images?.[String(p)];document.getElementById('source-dialog').innerHTML=`<div class="dialog-head"><div><h2>${s.id===5?'TD':'C'+s.id+' · '+E(chapter(s.id).short)} — ${s.id===5?'page':'diapositive'} ${p}</h2><div class="tiny muted" style="margin-top:3px">${E(s.name)}</div></div><button class="iconbtn" data-action="close-dialog" aria-label="Fermer la source">${icon('close')}</button></div><div class="source-toolbar"><div class="row"><button class="iconbtn" data-action="source-prev" ${p===1?'disabled':''} aria-label="Page source précédente">${icon('back')}</button><label class="tiny muted" for="source-page">Page</label><select id="source-page">${Array.from({length:s.count},(_,i)=>`<option value="${i+1}" ${i+1===p?'selected':''}>${i+1}</option>`).join('')}</select><span class="tiny muted">/ ${s.count}</span><button class="iconbtn" data-action="source-next" ${p===s.count?'disabled':''} aria-label="Page source suivante">${icon('arrow')}</button></div>${D.bundle?`<div class="row wrap"><a class="btn sm" target="_blank" rel="noopener" href="${E(s.path)}#page=${p}">${icon('external')} ${s.id===5?'PDF original':'Version PDF'}</a>${s.original?`<a class="btn sm" href="${E(s.original)}">PowerPoint original</a>`:''}</div>`:'<span class="tiny muted">Image intégrée · hors ligne</span>'}</div><div class="source-body">${img?`<img class="source-image" src="${img}" alt="${E(s.title)}, ${s.id===5?'page':'diapositive'} ${p}, support fourni.">`:''}<details class="source-extract"><summary>Afficher le texte extrait et les transcriptions</summary><p class="tiny muted">La disposition du texte suit l’extraction. L’image conserve la présentation du support.</p><pre class="source-text">${E(s.pages[p-1]||'Pas de texte extractible : consulter l’image ci-dessus.')}</pre></details></div>`;}
function showSearch(){const dlg=document.getElementById('search-dialog');dlg.innerHTML=`<div class="dialog-head"><div class="row" style="flex:1">${icon('search')}<label class="sr" for="global-query">Rechercher</label><input class="global-search-input" id="global-query" placeholder="Notion, artefact, chemin, commande…" autocomplete="off"></div><button class="iconbtn" data-action="close-dialog" aria-label="Fermer la recherche">${icon('close')}</button></div><div class="search-results" id="global-results"></div>`;if(!dlg.open)dlg.showModal();searchResults('');setTimeout(()=>document.getElementById('global-query')?.focus(),0);}
function searchResults(query){let results=[];if(!query.trim()){results=[{kind:'card',id:C[0].id,title:C[0].title,label:'Commencer les fondamentaux'},{kind:'atlas',id:A[0].id,title:A[0].name,label:'Un champ du handshake TLS'},{kind:'command',id:CM[0].id,title:CM[0].command,label:'Lire un filtre Wireshark'},{kind:'td',id:'kasiski',title:'TD · Kasiski et indice de coïncidence',label:'Calculs détaillés'}];}else{for(const c of C)if(matches([c.title,c.summary,...c.points,c.trap].join(' '),query))results.push({kind:'card',id:c.id,title:c.title,label:`Fiche · C${c.chapter}`,rank:matches(c.title,query)?0:2});for(const a of A)if(matches([a.name,a.path,a.purpose,a.tool].join(' '),query))results.push({kind:'atlas',id:a.id,title:a.name,label:`Repère · ${a.path}`,rank:matches(a.name,query)?0:3});for(const c of CM)if(matches([c.command,c.meaning,...c.parts].join(' '),query))results.push({kind:'command',id:c.id,title:c.command,label:`Commande · C${c.chapter}`,rank:matches(c.command,query)?0:3});for(const t of D.td)for(const x of t.items)if(matches(x.prompt,query)||matches(t.title,query))results.push({kind:'td',id:t.id,title:x.prompt,label:t.title,rank:2});for(const q of Q)if(matches(q.stem,query))results.push({kind:'question',id:q.id,title:q.stem,label:`Question d’entraînement · C${q.chapter}`,rank:4});results.sort((a,b)=>a.rank-b.rank);}document.getElementById('global-results').innerHTML=results.length?`<div class="tiny muted" style="padding:8px 14px">${query.trim()?`${results.length} résultats · les 25 premiers affichés`:'Quelques points de départ'}</div>${results.slice(0,25).map(r=>`<button class="search-result" data-action="search-result" data-kind="${r.kind}" data-id="${r.id}"><strong>${E(r.title)}</strong><small>${E(r.label)}</small></button>`).join('')}`:`<div class="empty" style="padding:30px"><h3>Aucun résultat pour cette recherche.</h3><p>Essaie un nom plus court ou un terme du support.</p></div>`;}
function download(name,text,type='application/json'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function printPaper(ids,title,attempt=null){const popup=window.open('','_blank');if(!popup){toast('Le navigateur bloque la fenêtre d’impression. Autorise les fenêtres pour ce fichier.');return;}const content=ids.map((id,i)=>{const q=QMap[id];return `<section><div class="meta">QUESTION ${i+1} · CHAPITRE ${q.chapter} · ${E(q.kind)}</div><h2>${E(q.stem)}</h2>${attempt?`<p><b>Réponse donnée :</b> ${Object.hasOwn(attempt.answers,id)?E(q.options[attempt.answers[id]]):'Aucune'}</p><p class="answer"><b>Réponse attendue :</b> ${E(q.options[q.answer])}</p><p>${E(q.explanation)}</p><p class="meta">Sources : ${refsOf(q).map(([c,p])=>c===5?'TD p. '+p:'C'+c+' diapo '+p).join(' ; ')}.${q.external?.length?' Complément : '+q.external.join(', '):''}</p>`:`<div>${q.options.map((o,j)=>`<p class="choice"><span>□ ${String.fromCharCode(65+j)}.</span> ${E(o)}</p>`).join('')}</div>`}</section>`}).join('');popup.document.write(`<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>${E(title)} · ${attempt?'Corrigé':'Sujet'} · TRACE</title><style>@page{size:A4;margin:17mm}body{font:12px/1.6 -apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif;color:#20242d;max-width:800px;margin:30px auto;padding:0 20px}header{border-bottom:2px solid #243859;padding-bottom:20px;margin-bottom:25px}h1{font-size:25px;margin:8px 0}h2{font-size:14px;line-height:1.5;margin:8px 0 14px}section{break-inside:avoid;border-bottom:1px solid #dfe3ea;padding:18px 0}.meta{font-size:9px;color:#657084;letter-spacing:.3px}p{margin:7px 0}.choice{padding-left:8px}.choice span{font-weight:600;margin-right:5px}.answer{padding:8px;background:#edf4f0}footer{font-size:9px;color:#687180;margin-top:20px}.controls{margin-bottom:20px}button{font:inherit;padding:9px 14px;cursor:pointer}@media print{body{margin:0;padding:0}.controls{display:none}}</style></head><body><div class="controls"><button onclick="window.print()">Imprimer / Enregistrer en PDF</button></div><header><div class="meta">TRACE · PROTOCOLES DE SÉCURITÉ & CRYPTANALYSE · ENTRAÎNEMENT NON OFFICIEL</div><h1>${E(title)} — ${attempt?'Corrigé expliqué':'Sujet'}</h1><p>${ids.length} questions · Une seule bonne réponse · 1 point par bonne réponse, 0 sinon.</p>${attempt?`<p><b>Résultat : ${score(attempt)} / ${ids.length}</b> · ${E(fmtDate(attempt.date))}</p>`:'<p>Nom : ________________________ &nbsp; Date : ________________________</p>'}<p class="meta">Exercices créés à partir des quatre cours et du TD fournis. Format et barème simulés, non communiqués par l’enseignant.</p></header>${content}<footer>Les références C1–C4 suivent l’ordre des diapositives ; TD renvoie aux pages du document de révision. Les sujets blancs 01 à 10 utilisent des questions distinctes ; les sélections personnalisées réutilisent cette banque.</footer></body></html>`);popup.document.close();popup.focus();}
function sanitizeState(raw){if(!raw||raw.app!=='TRACE-SECURITY'||raw.version!==1)throw new Error('Cette sauvegarde n’appartient pas au module Protocoles de sécurité & cryptanalyse.');const s=fresh();s.theme=raw.theme==='dark'?'dark':'light';s.defaultMinutes=[0,60,90,120].includes(Number(raw.defaultMinutes))?Number(raw.defaultMinutes):60;s.mastered=[...new Set(Array.isArray(raw.mastered)?raw.mastered:[])].filter(id=>CMap[id]);s.bookmarks=[...new Set(Array.isArray(raw.bookmarks)?raw.bookmarks:[])].filter(id=>CMap[id]);for(const [id,text] of Object.entries(raw.notes||{}))if(CMap[id]&&typeof text==='string')s.notes[id]=text.slice(0,20000);for(const [id,x] of Object.entries(raw.stats||{}))if(QMap[id]&&x&&typeof x.lastCorrect==='boolean')s.stats[id]={tries:Math.max(0,Number(x.tries)||0),correct:Math.max(0,Number(x.correct)||0),lastCorrect:x.lastCorrect,lastAt:Number(x.lastAt)||Date.now()};for(const [id,r] of Object.entries(raw.flashRatings||{}))if(QMap[id]&&['known','review'].includes(r))s.flashRatings[id]=r;s.lastCard=CMap[raw.lastCard]?raw.lastCard:null;s.sidebarCollapsed=raw.sidebarCollapsed===true;s.zen=raw.zen===true;s.focus=sanitizeFocus(raw.focus);
function cleanAttempt(a,active=false){if(!a||!Array.isArray(a.qids))return null;const ids=[...new Set(a.qids)].filter(id=>QMap[id]).slice(0,400);if(!ids.length)return null;const answers={},flags={},checked={};for(const id of ids){if(Number.isInteger(a.answers?.[id])&&a.answers[id]>=0&&a.answers[id]<4)answers[id]=a.answers[id];if(a.flags?.[id]===true)flags[id]=true;if(a.checked?.[id]===true)checked[id]=true;}const obj={id:/^attempt-[A-Za-z0-9-]+$/.test(a.id)?a.id:'attempt-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),examId:EX.some(e=>e.id===a.examId)?a.examId:null,title:String(a.title||'Session importée').slice(0,200),mode:a.mode==='practice'?'practice':'exam',qids:ids,answers,flags,duration:Number.isFinite(a.duration)&&a.duration>0?Math.min(86400,a.duration):null};if(active){obj.current=Math.max(0,Math.min(ids.length-1,Number(a.current)||0));obj.checked=checked;obj.startedAt=Number.isFinite(a.startedAt)?a.startedAt:Date.now();obj.deadline=Number.isFinite(a.deadline)?a.deadline:null;}else{obj.date=Number.isFinite(a.date)?a.date:Date.now();obj.elapsed=Math.max(0,Number(a.elapsed)||0);obj.timeout=Boolean(a.timeout);}return obj;}
s.attempts=(Array.isArray(raw.attempts)?raw.attempts:[]).slice(0,100).map(a=>cleanAttempt(a)).filter(Boolean);s.active=cleanAttempt(raw.active,true);const tm=Object.fromEntries(tdItems().map(t=>[t.id,t]));for(const [id,v] of Object.entries(raw.tdAnswers||{}))if(tm[id]&&typeof v==='string')s.tdAnswers[id]=v.slice(0,20000);for(const [id,v] of Object.entries(raw.tdChoices||{}))if(tm[id]?.options&&Number.isInteger(v)&&v>=0&&v<tm[id].options.length)s.tdChoices[id]=v;for(const key of ['tdDone','tdRevealed'])s[key]=[...new Set(Array.isArray(raw[key])?raw[key]:[])].filter(id=>tm[id]);return s;}
function refreshFiltered(kind){if(kind==='atlas'){document.getElementById('atlas-grid').innerHTML=atlasCards();document.getElementById('atlas-count').textContent=`${filteredAtlas().length} repères`;}else{document.getElementById('cmd-grid').innerHTML=commandCards();document.getElementById('cmd-count').textContent=`${filteredCommands().length} fiches`;}}
function relatedCard(q){return C.filter(c=>c.chapter===q.chapter).map(c=>({c,n:c.pages.filter(p=>q.pages.includes(p)).length})).sort((a,b)=>b.n-a.n)[0]?.c;}
function moveFlash(){if(!filters.flashDeck.length)return;filters.flashIdx=(filters.flashIdx+1)%filters.flashDeck.length;filters.flashBack=false;render();}
document.addEventListener('click',async ev=>{const target=ev.target.closest('[data-action]');if(ev.target.closest('.sidebar a')){document.getElementById('sidebar').classList.remove('open');document.getElementById('mobile-overlay').classList.remove('on');}if(!target||target.disabled)return;const action=target.dataset.action;try{switch(action){case 'go':go(target.dataset.route);break;case 'menu':document.getElementById('sidebar').classList.toggle('open');document.getElementById('mobile-overlay').classList.toggle('on');break;case 'theme':state.theme=state.theme==='dark'?'light':'dark';save();render();break;case 'search':showSearch();break;case 'close-dialog':target.closest('dialog')?.close();break;case 'source':openSource(target.dataset.ch,target.dataset.page);break;case 'source-prev':openSource(sourceView.chapter,sourceView.page-1);break;case 'source-next':openSource(sourceView.chapter,sourceView.page+1);break;case 'confirm-yes':case 'confirm-no':{document.getElementById('confirm-dialog').close();const resolve=confirmResolve;confirmResolve=null;resolve?.(action==='confirm-yes');break;}
case 'master':{const id=target.dataset.id;if(!CMap[id])break;const has=state.mastered.includes(id);state.mastered=has?state.mastered.filter(x=>x!==id):[...state.mastered,id];save();render();toast(has?'Fiche remise à étudier.':'Fiche marquée comme maîtrisée.');break;}
case 'bookmark':{const id=target.dataset.id;if(!CMap[id])break;const has=state.bookmarks.includes(id);state.bookmarks=has?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();render();toast(has?'Fiche retirée des favoris.':'Fiche gardée dans tes favoris.');break;}
case 'print-lesson':window.print();break;
case 'start-exam':{const ex=EX.find(e=>e.id===target.dataset.exam);if(ex)await startQuiz(ex.questions,ex.title,{mode:'exam',examId:ex.id,minutes:Number(getSelected('exam-minutes',state.defaultMinutes??60))});break;}
case 'custom-quiz':{const pool=customPool(),n=Math.min(Number(getSelected('custom-count',40)),pool.length),mode=getSelected('custom-mode','practice');await startQuiz(chooseBalanced(pool,n),`Sélection personnalisée · ${n} questions`,{mode});break;}
case 'chapter-quiz':{const ch=Number(target.dataset.ch);await startQuiz(shuffled(Q.filter(q=>q.chapter===ch).map(q=>q.id)).slice(0,40),`Entraînement · ${chapter(ch).short}`,{mode:'practice'});break;}
case 'command-quiz':{const ids=shuffled(Q.filter(q=>q.kind==='commande').map(q=>q.id)).slice(0,40);await startQuiz(ids,`Lecture de commandes · ${ids.length} questions`,{mode:'practice'});break;}
case 'random-quiz':await startQuiz(chooseBalanced(Q,40),'Nouvelle sélection · 40 questions',{mode:'practice'});break;
case 'errors-quiz':await startQuiz(shuffled(errorIds()).slice(0,40),'Revoir mes dernières erreurs',{mode:'practice'});break;
case 'retry-attempt':{const a=state.attempts.find(a=>a.id===target.dataset.attempt);if(a)await startQuiz(shuffled(a.qids.filter(id=>a.answers[id]!==QMap[id].answer)),`Reprise des erreurs · ${a.title}`,{mode:'practice'});break;}
case 'discard':if(state.active&&await ask('Abandonner cette session ?','Les réponses de la session non remise seront supprimées, sans modifier tes autres résultats.','Abandonner')){state.active=null;save();render();toast('Session abandonnée.');}break;
case 'answer':{const a=state.active;if(!a)break;const id=a.qids[a.current];if(a.mode==='practice'&&a.checked[id])break;a.answers[id]=Number(target.dataset.index);save();render();break;}
case 'flag':{const a=state.active;if(!a)break;const id=a.qids[a.current];a.flags[id]=!a.flags[id];save();render();break;}
case 'q-prev':case 'q-next':case 'q-jump':{const a=state.active;if(!a)break;a.current=Math.max(0,Math.min(a.qids.length-1,action==='q-jump'?Number(target.dataset.index):a.current+(action==='q-next'?1:-1)));save();render();if(innerWidth<=700)document.getElementById('question-title')?.scrollIntoView({block:'start',behavior:'auto'});break;}
case 'check-answer':{const a=state.active;if(!a)break;const id=a.qids[a.current];if(!Object.hasOwn(a.answers,id)){toast('Choisis une réponse avant de vérifier.');break;}a.checked[id]=true;save();render();break;}
case 'submit':await submitQuiz();break;
case 'related-card':{const q=QMap[target.dataset.q];if(q){const c=relatedCard(q);if(c)go(`chapter/${c.chapter}/${c.id}`);}break;}
case 'print-subject':{const ex=EX.find(e=>e.id===target.dataset.exam);if(ex)printPaper(ex.questions,ex.title);break;}
case 'print-correction':{const a=state.attempts.find(a=>a.id===target.dataset.attempt);if(a)printPaper(a.qids,a.title,a);break;}
case 'flash-flip':filters.flashBack=!filters.flashBack;render();break;case 'flash-next':moveFlash();break;case 'flash-shuffle':buildFlashDeck();render();break;case 'flash-rate':{const id=filters.flashDeck[filters.flashIdx];if(id){state.flashRatings[id]=target.dataset.rating;save();moveFlash();}break;}
case 'search-result':{const {kind,id}=target.dataset;closeDialogs();if(kind==='td')go('td/'+id);if(kind==='card'&&CMap[id])go(`chapter/${CMap[id].chapter}/${id}`);if(kind==='atlas'){const a=A.find(x=>x.id===id);if(a){filters.atlasCh='all';filters.atlasQ=a.name;go('atlas');}}if(kind==='command'){const c=CM.find(x=>x.id===id);if(c){filters.cmdCh='all';filters.cmdQ=c.command;go('commands');}}if(kind==='question'&&QMap[id])await startQuiz([id],'Question ciblée',{mode:'practice'});break;}
case 'export':download('TRACE-Protocoles-progression-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2));toast('Sauvegarde exportée.');break;case 'import':document.getElementById('import-file').click();break;case 'reset':if(await ask('Tout effacer sur cet appareil ?','Notes, favoris, maîtrise, historique, erreurs, sessions et données focus seront supprimés. Le contenu du cours restera disponible.','Réinitialiser')){const theme=state.theme;state=fresh();state.theme=theme;resetFocusRuntime();filters.flashDeck=[];save();render();toast('Progression réinitialisée.');}break;
}}catch(err){console.error(err);toast('Cette action n’a pas abouti. Ta progression déjà enregistrée reste conservée.');}});
document.addEventListener('input',ev=>{const t=ev.target;if(t.id==='atlas-query'){filters.atlasQ=t.value;refreshFiltered('atlas');}else if(t.id==='cmd-query'){filters.cmdQ=t.value;refreshFiltered('commands');}else if(t.id==='global-query')searchResults(t.value);else if(t.dataset.note&&CMap[t.dataset.note]){state.notes[t.dataset.note]=t.value;save();const s=document.getElementById('note-status');if(s)s.textContent=storageOK?'· enregistré sur cet appareil':'· export conseillé';}});
