function focusDefaults(){return {durations:{focus:25,short:5,long:15},phase:'focus',total:1500,remaining:1500,running:false,deadline:null,runStartedAt:null,phaseWorked:0,cycle:0,goal:'',chapter:1,sessionGoal:'',sessionChapter:1,parking:'',goalSessions:4,ledger:[],history:[],sound:true,ambientVolume:20,playlist:'37i9dQZF1DWWQRwui0ExPn',hasStarted:false,lastCompleted:null};}
function bounded(v,min,max,fallback){const n=Number(v);return Number.isFinite(n)?Math.max(min,Math.min(max,n)):fallback;}
function sanitizeFocus(raw){
 const f=focusDefaults();if(!raw||typeof raw!=='object')return f;
 for(const k of ['focus','short','long'])f.durations[k]=Math.round(bounded(raw.durations?.[k],1,k==='focus'?180:60,f.durations[k]));
 f.phase=['focus','short','long'].includes(raw.phase)?raw.phase:'focus';
 f.total=bounded(raw.total,1,10800,f.durations[f.phase]*60);f.remaining=bounded(raw.remaining,0,f.total,f.total);
 f.phaseWorked=bounded(raw.phaseWorked,0,10800,0);f.cycle=Math.floor(bounded(raw.cycle,0,100000,0));
 f.goal=typeof raw.goal==='string'?raw.goal.slice(0,180):'';f.parking=typeof raw.parking==='string'?raw.parking.slice(0,5000):'';
 f.chapter=CH.some(c=>c.id===Number(raw.chapter))?Number(raw.chapter):1;
 f.sessionGoal=typeof raw.sessionGoal==='string'?raw.sessionGoal.slice(0,180):f.goal;
 f.sessionChapter=CH.some(c=>c.id===Number(raw.sessionChapter))?Number(raw.sessionChapter):f.chapter;
 f.goalSessions=Math.round(bounded(raw.goalSessions,1,12,4));f.sound=raw.sound!==false;
 f.ambientVolume=bounded(raw.ambientVolume,0,100,20);
 f.playlist=/^[a-zA-Z0-9]{22}$/.test(raw.playlist)?raw.playlist:f.playlist;
 const validDay=d=>typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d);
 const ledgerMap=new Map();for(const x of (Array.isArray(raw.ledger)?raw.ledger:[]).slice(-500)){if(x&&validDay(x.day))ledgerMap.set(x.day,bounded(x.seconds,0,86400,0));}
 f.ledger=[...ledgerMap].map(([day,seconds])=>({day,seconds})).sort((a,b)=>a.day.localeCompare(b.day));
 f.history=(Array.isArray(raw.history)?raw.history:[]).slice(0,500).filter(x=>x&&Number.isFinite(x.at)&&x.at>0&&x.at<=Date.now()+86400000).map(x=>({at:x.at,seconds:bounded(x.seconds,0,10800,0),goal:String(x.goal||'Session de révision').slice(0,180),chapter:CH.some(c=>c.id===Number(x.chapter))?Number(x.chapter):1}));
 f.hasStarted=raw.hasStarted===true;
 if(raw.lastCompleted&&typeof raw.lastCompleted.text==='string')f.lastCompleted={text:raw.lastCompleted.text.slice(0,250),at:bounded(raw.lastCompleted.at,0,Date.now(),0)};
 if(raw.running===true&&Number.isFinite(raw.deadline)&&Number.isFinite(raw.runStartedAt)&&raw.deadline>raw.runStartedAt&&raw.deadline-raw.runStartedAt<=10800001&&raw.runStartedAt<=Date.now()+1000&&raw.deadline<=Date.now()+10800001){f.running=true;f.deadline=raw.deadline;f.runStartedAt=raw.runStartedAt;f.hasStarted=true;}
 return f;
}
