function focusToday(){const f=state.focus;let seconds=f.ledger.find(x=>x.day===localDay())?.seconds||0;const now=Date.now();if(f.running&&f.phase==='focus'){const d=new Date(now);d.setHours(0,0,0,0);seconds+=Math.max(0,(Math.min(now,f.deadline)-Math.max(f.runStartedAt,d.getTime()))/1000);}return {seconds,sessions:f.history.filter(x=>localDay(x.at)===localDay()).length};}
function recordWork(start,end){
 if(!(end>start))return;
 const f=state.focus;
 while(start<end){const day=localDay(start),next=new Date(start);next.setHours(24,0,0,0);const stop=Math.min(end,next.getTime());let row=f.ledger.find(x=>x.day===day);if(!row){row={day,seconds:0};f.ledger.push(row);}row.seconds=Math.min(86400,row.seconds+(stop-start)/1000);start=stop;}
 f.ledger.sort((a,b)=>a.day.localeCompare(b.day));f.ledger=f.ledger.slice(-500);
}
