function setFocusPhase(phase){const f=state.focus;f.phase=phase;f.total=f.durations[phase]*60;f.remaining=f.total;f.phaseWorked=0;f.running=false;f.deadline=null;f.runStartedAt=null;f.sessionGoal='';f.sessionChapter=f.chapter;}
async function ensureAudio(){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw new Error('Ce navigateur ne prend pas en charge les sons locaux.');if(!audioContext)audioContext=new AC();if(audioContext.state==='suspended')await audioContext.resume();return audioContext;}
async function playFinishChime(){if(!state.focus.sound||!audioContext)return;try{if(audioContext.state!=='running')return;const now=audioContext.currentTime;[660,880].forEach((freq,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(0,now+i*.22);g.gain.linearRampToValueAtTime(.065,now+i*.22+.025);g.gain.exponentialRampToValueAtTime(.001,now+i*.22+.45);o.connect(g);g.connect(audioContext.destination);o.start(now+i*.22);o.stop(now+i*.22+.5);});}catch(e){/* Timer completion remains functional without sound. */}}
